export class ToastStates {
  readonly entry = input.required<number>()
  readonly overrides = input<Readonly<Record<string, unknown>>>({})

  protected e1(): ToastProps['action'] {
    return {
      label: 'Undo',
      onClick: () =>
        document.dispatchEvent(new CustomEvent('polymorph:fixturecall', { detail: 'onClick' })),
    }
  }

  protected e2() {
    return (() =>
      document.dispatchEvent(
        new CustomEvent('polymorph:fixturecall', { detail: 'onDismiss' }),
      )) as (...args: unknown[]) => unknown
  }

  protected e3(): ToastProps['durationMs'] {
    return Number.POSITIVE_INFINITY
  }

  protected e4() {
    return (() =>
      document.dispatchEvent(
        new CustomEvent('polymorph:fixturecall', { detail: 'onDismiss' }),
      )) as (...args: unknown[]) => unknown
  }

  protected e5(): ToastProps['durationMs'] {
    return Number.POSITIVE_INFINITY
  }

  protected e6() {
    return (() =>
      document.dispatchEvent(
        new CustomEvent('polymorph:fixturecall', { detail: 'onDismiss' }),
      )) as (...args: unknown[]) => unknown
  }

  protected e7(): ToastProps['durationMs'] {
    return Number.POSITIVE_INFINITY
  }

  protected e8() {
    return (() =>
      toast({
        title: 'Neutral',
        description: 'The tone speaks through the glyph and nothing else.',
        tone: 'neutral',
      })) as (...args: unknown[]) => unknown
  }

  protected e9() {
    return (() =>
      toast({
        title: 'Success',
        description: 'The tone speaks through the glyph and nothing else.',
        tone: 'success',
      })) as (...args: unknown[]) => unknown
  }

  protected e10() {
    return (() =>
      toast({
        title: 'Danger',
        description: 'The tone speaks through the glyph and nothing else.',
        tone: 'danger',
      })) as (...args: unknown[]) => unknown
  }

  protected e11() {
    return (() =>
      toast({
        title: 'Warning',
        description: 'The tone speaks through the glyph and nothing else.',
        tone: 'warning',
      })) as (...args: unknown[]) => unknown
  }

  protected e12() {
    return (() =>
      toast({
        title: 'Info',
        description: 'The tone speaks through the glyph and nothing else.',
        tone: 'info',
      })) as (...args: unknown[]) => unknown
  }

  protected e13(): InlineProps['gap'] {
    return 2
  }

  protected e14(): InlineProps['wrap'] {
    return true
  }

  protected e15() {
    return (() =>
      toast.success('Ticket archived', {
        action: { label: 'Undo', onClick: () => undefined },
      })) as (...args: unknown[]) => unknown
  }

  protected e16() {
    return (() =>
      toast.danger('Could not delete', {
        description: 'The ticket is referenced by another.',
        action: { label: 'Retry', onClick: () => undefined },
      })) as (...args: unknown[]) => unknown
  }

  protected e17(): InlineProps['gap'] {
    return 2
  }

  protected e18(): InlineProps['wrap'] {
    return true
  }

  protected e19() {
    return (() =>
      toast({
        title: 'Still working',
        description: 'This one has no timer.',
        durationMs: Number.POSITIVE_INFINITY,
      })) as (...args: unknown[]) => unknown
  }

  protected e20(): InlineProps['gap'] {
    return 2
  }

  protected e21(): InlineProps['wrap'] {
    return true
  }

  protected e22() {
    return (() =>
      toast.promise(new Promise((resolve) => setTimeout(resolve, 2500)), {
        loading: 'Archiving ticket…',
        success: 'Ticket archived',
        error: 'Could not archive',
      })) as (...args: unknown[]) => unknown
  }

  protected e23() {
    return (() =>
      toast.promise(new Promise((_, reject) => setTimeout(reject, 2500)), {
        loading: 'Archiving ticket…',
        success: 'Ticket archived',
        error: { title: 'Could not archive', description: 'The queue is read-only.' },
      })) as (...args: unknown[]) => unknown
  }

  protected e24(): InlineProps['gap'] {
    return 2
  }

  protected e25(): InlineProps['wrap'] {
    return true
  }

  protected e26() {
    return (() => {
      toast({ id: 'update-demo', title: 'Exporting 0 of 3…', durationMs: Number.POSITIVE_INFINITY })
      setTimeout(
        () =>
          toast({
            id: 'update-demo',
            title: 'Exporting 2 of 3…',
            durationMs: Number.POSITIVE_INFINITY,
          }),
        1200,
      )
      setTimeout(() => toast({ id: 'update-demo', title: 'Export ready', tone: 'success' }), 2400)
    }) as (...args: unknown[]) => unknown
  }

  protected e27(): InlineProps['gap'] {
    return 2
  }

  protected e28(): InlineProps['wrap'] {
    return true
  }

  protected e29() {
    return (() => {
      for (let index = 1; index <= TOAST_MAX_VISIBLE; index += 1)
        toast({ title: `Toast ${index}`, durationMs: Number.POSITIVE_INFINITY })
    }) as (...args: unknown[]) => unknown
  }

  protected e30() {
    return (() => {
      for (let index = 1; index <= TOAST_MAX_VISIBLE + 3; index += 1)
        toast({ title: `Overflow ${index}` })
    }) as (...args: unknown[]) => unknown
  }

  protected e31() {
    return (() => toast.dismiss()) as (...args: unknown[]) => unknown
  }

  protected e32(): InlineProps['gap'] {
    return 2
  }

  protected e33(): InlineProps['wrap'] {
    return true
  }
}

